"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/feature-sections/variants/01-visual-benefits";
import View1 from "./components/feature-sections/variants/02-alternating-rows";
import View2 from "./components/feature-sections/variants/03-product-hotspots";
import View3 from "./components/feature-sections/variants/04-showcase";
import View4 from "./components/feature-sections/variants/05-benefits-triptych";
import View5 from "./components/feature-sections/variants/06-signal-grid";
import View6 from "./components/feature-sections/variants/07-control-deck";
import View7 from "./components/feature-sections/variants/08-voice-ai";
import View8 from "./components/feature-sections/variants/09-list";
import View9 from "./components/feature-sections/variants/10-steps";
import View10 from "./components/feature-sections/variants/11-bento";
import View11 from "./components/feature-sections/variants/12-tabs";
import View12 from "./components/feature-sections/variants/13-stage-tabs";
const variants = {"visual-benefits":View0,"alternating-rows":View1,"product-hotspots":View2,"showcase":View3,"benefits-triptych":View4,"signal-grid":View5,"control-deck":View6,"voice-ai":View7,"list":View8,"steps":View9,"bento":View10,"tabs":View11,"stage-tabs":View12};
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "visual-benefits" | "alternating-rows" | "product-hotspots" | "showcase" | "benefits-triptych" | "signal-grid" | "control-deck" | "voice-ai" | "list" | "steps" | "bento" | "tabs" | "stage-tabs"; }
export function ArtemisFeatureSections({ className, variant = "visual-benefits" }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
